main.script:
function toggleAllVendors(checkbox) {
    var checkboxes = document.querySelectorAll('.vendor-checkbox');
    checkboxes.forEach(function(cb) {
        cb.checked = checkbox.checked;
    });
}

function validateApproval() {
    var checkboxes = document.querySelectorAll('.vendor-checkbox:checked');
    var alert = document.getElementById('no_vendor_selected_alert');
    if (checkboxes.length === 0) {
        alert.classList.remove('d-none');
        return false;
    }
    alert.classList.add('d-none');
    return true;
}
